WITH unpacked AS (SELECT id, coupon_codes, items, attributes, TRANSFORM(FILTER(items, i -> i.promo IS NOT NULL), i -> STRUCT(i.product_id AS pid, ROUND(i.price * 0.9, 2) AS discounted_price)) AS promo_lines, COALESCE(attributes['gift'], 'direct') AS gift_or_default, attributes['utm_source'] AS utm_source, AGGREGATE(items, CAST(0 AS DOUBLE), (acc, i) -> acc + i.qty * i.price, acc -> ROUND(acc, 2)) AS basket_amount FROM carts) SELECT CASE WHEN basket_amount >= 1240 THEN 'HIGH' ELSE 'LOW' END AS basket_amount_tier, PERCENTILE_APPROX(basket_amount, 0.9) AS basket_amount_p90, APPROX_PERCENTILE(basket_amount, 0.5) AS basket_amount_p50, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(basket_amount, 0.5) AS basket_amount_p50_2 FROM unpacked GROUP BY CASE WHEN basket_amount >= 1240 THEN 'HIGH' ELSE 'LOW' END ORDER BY basket_amount_tier DESC;
